/**
 * Lazy loading for the per-locale catalogs generated by
 * scripts/build-i18n-catalogs.mjs.
 *
 * Kept apart from the pure lookup/formatting logic in ./catalog so unit tests
 * (and any non-bundled consumer) do not need the generated chunk loaders.
 */
import type { Catalog } from "./catalog";
import { catalogLoaders } from "./catalogs/loaders";

const catalogCache = new Map<string, Promise<Catalog>>();

/**
 * Loads (and memoizes) the catalog chunk for a locale. Each locale is its own
 * named chunk (`i18n/<locale>.<hash>.js`) so the server can modulepreload the
 * active one and locale switches only fetch the new language.
 */
export function loadCatalog(locale: string): Promise<Catalog> {
  const cached = catalogCache.get(locale);

  if (cached) return cached;

  const loader = catalogLoaders[locale];

  if (!loader) {
    return Promise.reject(new Error(`[i18n] no catalog chunk for locale "${locale}"`));
  }

  const promise = loader().then((module) => module.default ?? (module as unknown as Catalog));

  catalogCache.set(locale, promise);

  // A failed import (offline, chunk evicted) must not be memoized forever.
  promise.catch(() => {
    catalogCache.delete(locale);
  });

  return promise;
}
